class Solution { int[] parent,size;private int find(int x){return parent[x]==x?x:(parent[x]=find(parent[x]));}private void union(int a,int b){a=find(a);b=find(b);if(a==b)return;if(size[a]<size[b]){int t=a;a=b;b=t;}parent[b]=a;size[a]+=size[b];}public int numberOfGoodPaths(int[] vals,int[][] edges){int n=vals.length;List<Integer>[] graph=new List[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}Integer[] order=new Integer[n];for(int i=0;i<n;i++)order[i]=i;Arrays.sort(order,Comparator.comparingInt(i->vals[i]));parent=new int[n];size=new int[n];boolean[] active=new boolean[n];for(int i=0;i<n;i++){parent[i]=i;size[i]=1;}int answer=n;for(int start=0;start<n;){int end=start;while(end<n&&vals[order[end]]==vals[order[start]])end++;for(int p=start;p<end;p++){int node=order[p];active[node]=true;for(int next:graph[node])if(active[next])union(node,next);}Map<Integer,Integer> count=new HashMap<>();for(int p=start;p<end;p++)count.merge(find(order[p]),1,Integer::sum);for(int c:count.values())answer+=c*(c-1)/2;start=end;}return answer;} }
